{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    # Build maps
    nodes_by_id = {}
    children = {}  # id -> list of child ids
    for node in nodes:
        nid = node['id']
        nodes_by_id[nid] = node
        children.setdefault(node['parent'], []).append(nid)

    # Identify root
    root_id = None
    for nid, node in nodes_by_id.items():
        if node['parent'] is None:
            root_id = nid
            break
    if root_id is None:
        raise ValueError('No root node (parent=None)')
    root = nodes_by_id[root_id]
    if root['removable']:
        raise ValueError('Root node is marked removable')

    # Validate required symbols exist
    all_symbols = {node['symbol'] for node in nodes}
    for sym in required_symbols:
        if sym not in all_symbols:
            raise ValueError(f'Required symbol {sym} not found in any node')

    # Sort nodes: deeper depth first, then node id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    retained = {n['id'] for n in nodes}
    removed = []

    for node in sorted_nodes:
        nid = node['id']
        if nid == root_id:
            continue
        if not node['removable']:
            continue
        if node['symbol'] in required_symbols:
            continue
        # Check retained children
        child_ids = children.get(nid, [])
        if any(cid in retained for cid in child_ids):
            continue
        # Remove node
        retained.remove(nid)
        removed.append(nid)

    retained_node_ids = sorted(retained)
    removed_node_ids = removed

    return {
        'removed_node_ids': removed_node_ids,
        'retained_node_ids': retained_node_ids
    }"
}
